INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1357329-me489', 'stk-new_fresh', 'ME 489', 'info', '{"desc": "المادة نوعا ما حلوة بحيث انك تخليك ملم اكثر باللي اخذته في 307\nبعني تقدر تشيل اي مسألة لحساب الفورس ولا السترس او حتى من 315 وتقدر ترسمها في البرنامج ويعطيك الناتج على هذا الشكل\n\nhttps://engineering.purdue.edu/AAE/Academics/Courses/Raisbeck/images/resources/ansys_stress.jpg\n\nوتطلع منه الشي اللي تبغا تحسبه مثلا في الصورة اعلى قيمة للستريس 3195\n\nولو تقسم ال yield stress / 3195 يعطيك السيفتي فاكتور واخطر نقطة عندك في المنطقة الحمراء في الصورة\n\nهذي الجزئية اللي عجبتني في الكورس ومنزلها عشان اتعلم عليها ، ولكن في قسم نظري في المادة يعني يعطيك سؤال . طبعا اسهل من اللي في الصورة ويقلك قسمه الى قطع وطبق عليه المعادلات ، (في الاختبار انت تسوي الفورملاشيت - عند د. ابو الفضل عارف)\nوالمعادلات تطبقها في ماتريكس (مصفوفات) .\nملاحظة: البرنامج المستخدم في الصورة هو نفس البرنامج اللي بتشتغلوا عليه ANSYS 14\n\nمن الاخر المادة اذا بتنزلها عشان تستفيد خذها، اما لو تبغا مادة سهلة وماهمتك المعلومات كثير ما اتوقع ان الفاينات خيارك الانسب :ninja:\n\nللمعلومية الميجر الاول للمادة نظري فقط والميجر الثاني نظري ساعة وربع تقريبا وبعدها يعطيكم مسألة على البرنامج يقلكم سلمه لي قبل الساعة كذأ (عندنا تقريبا 12 ساعة من اول ما استلمنا المسألة).", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/finite-element-me-489/160129/5", "user": "new_fresh", "ts": 1398376205000, "tid": 160129, "pn": 5}}', 1398376205000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
